'use strict';
const $=selector=>document.querySelector(selector);
const music=$('#music'),musicToggle=$('#music-toggle'),musicLabel=$('#music-label');
function setMusicState(){const playing=!music.paused;musicToggle.setAttribute('aria-pressed',String(playing));musicToggle.setAttribute('aria-label',playing?'Jeda musik':'Putar musik');musicLabel.textContent=playing?'Jeda musik':'Putar musik';}
async function playMusic(){try{await music.play();}catch{}setMusicState();}
musicToggle.addEventListener('click',async()=>{if(music.paused)await playMusic();else{music.pause();setMusicState();}});
music.addEventListener('play',setMusicState);music.addEventListener('pause',setMusicState);
// Browsers may block audible autoplay. A first gesture retries without obstructing reading.
document.addEventListener('pointerdown',event=>{if(!event.target.closest('#music-toggle')&&music.paused)playMusic();},{once:true});
document.addEventListener('keydown',()=>{if(document.activeElement!==musicToggle&&music.paused)playMusic();},{once:true});
function safeMap(value){try{const url=new URL(value);return url.protocol==='https:'&&['maps.app.goo.gl','www.google.com','google.com','maps.google.com'].includes(url.hostname)?url.href:null;}catch{return null;}}
function dateText(raw,options){if(!/^\d{4}-\d{2}-\d{2}$/.test(raw||''))return 'Tanggal akan diinformasikan';return new Date(raw+'T12:00:00').toLocaleDateString('id-ID',options);}
function countdown(raw){if(!/^\d{4}-\d{2}-\d{2}$/.test(raw||''))return;const target=new Date(raw+'T00:00:00+07:00').getTime(),days=Math.ceil((target-Date.now())/86400000);$('#countdown').textContent=days>0?days+' hari menuju hari bahagia':days===0?'Hari bahagia telah tiba':'Terima kasih telah merayakan bersama kami';}
async function loadInvitation(){try{const response=await fetch('/api/invite/public',{cache:'no-store',signal:AbortSignal.timeout(12000)});const data=await response.json();if(!response.ok||!data.event)throw Error(data.error||'Undangan belum tersedia.');const event=data.event,w=event.wedding||{};const first=w.firstName||'Cesar',second=w.secondName||'Revalina';$('#first-name').textContent=first;$('#second-name').textContent=second;$('#signature').textContent=first+' & '+second;$('#closing-names').textContent=first+' & '+second;$('#cover-date').textContent=dateText(event.date,{day:'numeric',month:'long',year:'numeric'});$('#event-date').textContent=dateText(event.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#cover-venue').textContent=w.venue||'Tempat akan diinformasikan';$('#venue').textContent=w.venue||'Tempat akan diinformasikan';$('#address').textContent=w.address||'Bandung, Jawa Barat';$('#ceremony-time').textContent=w.ceremonyTime||'Waktu akan diinformasikan';$('#reception-time').textContent=w.receptionTime||'Waktu akan diinformasikan';const map=safeMap(w.mapsURL);$('#maps-link').hidden=!map;if(map)$('#maps-link').href=map;countdown(event.date);document.title=first+' & '+second+' — Undangan Pernikahan';$('#invitation').hidden=false;$('#load-error').hidden=true;const video=$('#hero-video');video.src='/api/invite/public-media/film.mp4';video.play().catch(()=>{});playMusic();}catch(error){$('#error-message').textContent=error.message||'Periksa koneksi dan coba lagi.';$('#load-error').hidden=false;}}
$('#retry').addEventListener('click',loadInvitation);loadInvitation();
